// Up to 40 creators a week: active ones first, then suggested ones (oldest scan first)
const clean = h => String(h || '').trim().replace(/^@/, '').replace(/\/$/, '').split('/').pop().toLowerCase();
const rows = $('Read Creators').all().map(i => i.json).filter(r => clean(r.handle));
const st = r => String(r.status || '').trim().toLowerCase();
const age = r => (r.last_scanned ? new Date(r.last_scanned).getTime() : 0) || 0;
const active = rows.filter(r => st(r) === 'active' || st(r) === '').sort((a, b) => age(a) - age(b));
const suggested = rows.filter(r => st(r) === 'suggested').sort((a, b) => age(a) - age(b));
const F = '{username,name,biography,website,followers_count,media_count,media.limit(25){caption,permalink,timestamp}}';
return [...active, ...suggested].slice(0, 40).map(r => {
  const handle = clean(r.handle);
  return { json: { handle, status: st(r) || 'active', fields: `business_discovery.username(${handle})${F}` } };
});

// Scores each creator against our own profile and pulls their sponsored posts
const MIN_SIM = 20, MIN_FOLLOWERS = 1000, MAX_FOLLOWERS = 300000;
const DAYS = 365;
const STOP = new Set('the and for you your with this that are our was have has from but not all can just what when out new get got its it\'s one more about how they them their will who make made into like love here there day today week year time back been some very also than then which would could should these those over only even most much many really thing things want need see let lets dont don\'t isnt didnt cant http https www com link bio comment comments post posts follow share save'.split(' '));
const TOPICS = ['design','designer','brand','branding','logo','logos','marketing','social','socialmedia','content','creative','creator','studio','agency','nonprofit','nonprofits','smallbusiness','business','website','websites','web','typography','type','illustration','graphic','graphicdesign','canva','figma','adobe','photography','newsletter','strategy','mission','community','minneapolis','barcelona','freelance','entrepreneur'];
const words = t => (String(t || '').toLowerCase().match(/[a-z][a-z0-9']{2,}/g) || []).filter(w => !STOP.has(w));
function vec(bio, captions) {
  const v = {};
  words(bio).forEach(w => v[w] = (v[w] || 0) + 3);
  captions.forEach(c => words(c).forEach(w => v[w] = (v[w] || 0) + 1));
  return v;
}
function similarity(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (const k in a) { na += a[k] * a[k]; if (b[k]) dot += a[k] * b[k]; }
  for (const k in b) nb += b[k] * b[k];
  const cos = na && nb ? dot / Math.sqrt(na * nb) : 0;
  const mine = TOPICS.filter(t => a[t]);
  const shared = mine.filter(t => b[t]).length;
  const topic = mine.length ? Math.min(1, shared / Math.min(mine.length, 6)) : 0;
  return Math.round(100 * (0.5 * Math.min(1, cos * 2) + 0.5 * topic));
}
const DEAL = /(#ad\b|#ads\b|#sponsored|#spon\b|#paidpartnership|#partner\b|#brandpartner|#ambassador|#[a-z0-9]+partner\b|#[a-z0-9]+ambassador\b|#gifted|paid partnership|in partnership with|partnered with|partnering with|sponsored by|thanks to @|thank you @|use (my )?code|discount code|promo code|affiliate link|#collab\b)/i;
const IGNORE = new Set(['gmail.com', 'instagram', 'threads', 'youtube', 'tiktok', 'linkedin']);
function dealBrands(caption, self) {
  const out = new Set();
  (caption.match(/@([a-z0-9._]{2,30})/gi) || []).forEach(m => {
    const h = m.slice(1).toLowerCase().replace(/\.+$/, '');
    if (h && h !== self && !IGNORE.has(h)) out.add(h);
  });
  if (!out.size) (caption.match(/#([a-z0-9]{3,25})(partner|ambassador)\b/gi) || []).forEach(m => {
    const h = m.slice(1).toLowerCase().replace(/(partner|ambassador)$/, '');
    if (h && h !== 'brand' && h !== 'paid') out.add(h);
  });
  return [...out];
}

const me = $('IG: my profile').first().json;
const myVec = vec(me.biography, ((me.media && me.media.data) || []).map(m => m.caption || ''));
const asked = $('Creators to scan').all().map(i => i.json);
const now = new Date().toISOString();
const cutoff = Date.now() - DAYS * 864e5;

return $input.all().map((item, idx) => {
  const ask = asked[idx] || {};
  const bd = item.json.business_discovery;
  if (!bd) {
    return { json: { handle: ask.handle, status: ask.status === 'suggested' ? 'skip' : ask.status, last_scanned: now,
      handle_check: 'not found, or a personal account (only creator/business accounts can be read)', _deals: [] } };
  }
  const media = (bd.media && bd.media.data) || [];
  const sim = similarity(myVec, vec(bd.biography, media.map(m => m.caption || '')));
  const deals = media.filter(m => m.caption && DEAL.test(m.caption) && new Date(m.timestamp).getTime() >= cutoff)
    .map(m => ({ permalink: m.permalink, timestamp: m.timestamp, brands: dealBrands(m.caption, bd.username.toLowerCase()) }))
    .filter(d => d.brands.length);
  const count = {};
  deals.forEach(d => d.brands.forEach(b => count[b] = (count[b] || 0) + 1));
  const top = Object.entries(count).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([b]) => '@' + b).join(', ');
  let status = ask.status;
  if (status === 'suggested') {
    const f = bd.followers_count || 0;
    status = sim >= MIN_SIM && f >= MIN_FOLLOWERS && f <= MAX_FOLLOWERS ? 'active' : 'skip';
  }
  return { json: { handle: ask.handle, status, name: bd.name || '', followers: bd.followers_count || '', similarity: sim,
    deal_posts: deals.length, top_brands: top, last_scanned: now, handle_check: 'ok', _deals: deals } };
});

// Brands that similar creators tagged in sponsored posts, merged with what the Brands tab already knows
const clean = h => String(h || '').trim().replace(/^@/, '').toLowerCase();
const list = s => String(s || '').split(/[,\s]+/).map(clean).filter(Boolean);
const creators = new Set($('Read Creators').all().map(i => clean(i.json.handle)).filter(Boolean));
const known = new Map($('Read Brands').all().map(i => i.json).filter(r => clean(r.handle)).map(r => [clean(r.handle), r]));
const agg = {};
for (const { json: c } of $('Creator results').all()) {
  if (c.status !== 'active') continue;
  for (const d of c._deals || []) for (const b of d.brands) {
    if (creators.has(b)) continue;
    const a = agg[b] = agg[b] || { creators: new Set(), posts: 0, example: '', last: '' };
    a.creators.add(c.handle); a.posts++;
    if (!a.last || d.timestamp > a.last) { a.last = d.timestamp; a.example = d.permalink; }
  }
}
const out = [];
for (const [handle, a] of Object.entries(agg)) {
  const k = known.get(handle) || {};
  if (['skip', 'not a brand'].includes(String(k.status || '').toLowerCase())) continue;
  list(k.creator_handles).forEach(h => a.creators.add(h));
  const prevPosts = Number(k.deal_posts) || 0;
  out.push({ handle, isNew: !known.has(handle), status: k.status || 'new',
    creators_seen: a.creators.size, creator_handles: [...a.creators].map(h => '@' + h).join(', '),
    deal_posts: Math.max(prevPosts, a.posts), example_post: a.example || k.example_post || '',
    last_seen: a.last ? a.last.slice(0, 10) : (k.last_seen || '') });
}
// New brands and brands seen with the most creators first; 40 lookups a week keeps us far under Instagram's limit
out.sort((x, y) => (y.isNew - x.isNew) || (y.creators_seen - x.creators_seen) || (y.deal_posts - x.deal_posts));
const F = '{username,name,biography,website,followers_count,media_count,media.limit(25){caption}}';
return out.slice(0, 40).map(b => ({ json: { ...b, fields: `business_discovery.username(${b.handle})${F}` } }));

// Adds each brand's profile and builds the question for the local AI model (LM Studio)
const ABOUT = 'Open Frame is a small design and marketing studio (Minneapolis and Barcelona) that posts about branding, logos, websites, social media and marketing for mission-driven organizations, nonprofits and small brands.';
const SYSTEM = 'You sort Instagram accounts for a creator looking for brand deals. Reply only with JSON.';
const asked = $('Brand candidates').all().map(i => i.json);
return $input.all().map((item, idx) => {
  const b = { ...asked[idx] };
  delete b.fields;
  const bd = item.json.business_discovery;
  if (!bd) return { json: { ...b, handle_check: 'not found, or a personal account', tagged: [], llm: null } };
  const tagged = new Set();
  ((bd.media && bd.media.data) || []).forEach(m => (String(m.caption || '').match(/@([a-z0-9._]{2,30})/gi) || [])
    .forEach(t => { const h = t.slice(1).toLowerCase().replace(/\.+$/, ''); if (h !== b.handle) tagged.add(h); }));
  const user = `${ABOUT}\n\nAccount: @${bd.username}\nName: ${bd.name || ''}\nFollowers: ${bd.followers_count || 0}\nWebsite: ${bd.website || ''}\nBio: ${String(bd.biography || '').slice(0, 400)}\n\n` +
    'Answer:\n- type: "brand" if this is a company or product that pays creators, "creator" if it is a person or creator, "other" for media, events, agencies or anything else.\n' +
    '- fit: "high", "medium" or "low" for how likely this brand would sponsor Open Frame\'s content.\n- why: one plain sentence, max 15 words.';
  return { json: { ...b, name: bd.name || '', followers: bd.followers_count || '', website: bd.website || '',
    bio: String(bd.biography || '').replace(/\s+/g, ' ').slice(0, 200), handle_check: 'ok', tagged: [...tagged].slice(0, 15),
    llm: { model: 'google/gemma-4-e4b', temperature: 0.2, max_tokens: 200,
      messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: user }],
      response_format: { type: 'json_schema', json_schema: { name: 'brand_fit', strict: true, schema: { type: 'object',
        properties: { type: { type: 'string', enum: ['brand', 'creator', 'other'] }, fit: { type: 'string', enum: ['high', 'medium', 'low'] }, why: { type: 'string' } },
        required: ['type', 'fit', 'why'] } } } } } };
});

// Reads the local AI's answer. If LM Studio is off, the brand is still saved, just without fit and why
const prev = $('Brand profiles').all().map(i => i.json);
const now = new Date().toISOString();
return $input.all().map((item, idx) => {
  const b = { ...prev[idx] };
  let ai = {};
  if (b.handle_check === 'ok') try {
    const txt = item.json.choices[0].message.content;
    ai = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1));
  } catch (e) { ai = {}; }
  const type = b.handle_check !== 'ok' ? 'unknown' : (ai.type || 'brand');
  delete b.llm;
  return { json: { ...b, type, fit: type === 'unknown' ? '' : (ai.fit || ''), why: type === 'unknown' ? 'Check the handle on Instagram' : String(ai.why || '').slice(0, 140), last_checked: now } };
});

// Every looked-up account is saved so it isn't looked up again. People and media accounts get status "not a brand"
return $input.all().map(i => {
  const b = i.json;
  const status = b.type === 'creator' || b.type === 'other' ? 'not a brand' : b.status;
  return { json: { handle: b.handle, name: b.name || '', status, fit: b.fit, why: b.why, creators_seen: b.creators_seen,
    creator_handles: b.creator_handles, deal_posts: b.deal_posts, followers: b.followers || '', website: b.website || '',
    example_post: b.example_post, last_seen: b.last_seen, bio: b.bio || '', handle_check: b.handle_check, last_checked: b.last_checked } };
});

// Snowball: creators that brands tag, plus "brands" that turned out to be people, become suggested creators.
// They get scanned next week and switch to active or skip on their own.
const clean = h => String(h || '').trim().replace(/^@/, '').toLowerCase();
const have = new Set([...$('Read Creators').all(), ...$('Read Brands').all()].map(i => clean(i.json.handle)).filter(Boolean));
const brandSet = new Set($input.all().map(i => i.json.handle));
const out = new Map();
for (const { json: b } of $input.all()) {
  if (b.type === 'creator' && !have.has(b.handle)) out.set(b.handle, `looked like a brand, is a creator (seen with ${b.creator_handles})`);
  if (b.type !== 'brand') continue;
  for (const t of b.tagged || []) if (!have.has(t) && !brandSet.has(t) && !out.has(t)) out.set(t, `tagged by @${b.handle}`);
}
return [...out].slice(0, 30).map(([handle, source]) => ({ json: { handle, status: 'suggested', source } }));
